using Microsoft.EntityFrameworkCore;

public sealed class PlaceOrder(ShopDb db)
{
    public async Task<int> RunAsync(int cartId, CancellationToken ct)
    {
        // Needed only because the save is split; throws when retries are on
        await using var tx = await db.Database.BeginTransactionAsync(ct);
        var cart = await db.Carts.Include(c => c.Items)
            .SingleAsync(c => c.Id == cartId, ct);
        var order = new Order { CustomerId = cart.CustomerId };
        db.Orders.Add(order);
        await db.SaveChangesAsync(ct); // only to get order.Id
        db.OrderLines.AddRange(cart.Items.Select(i => i.ToLine(order.Id)));
        db.Carts.Remove(cart);
        await db.SaveChangesAsync(ct);
        await tx.CommitAsync(ct);
        return order.Id;
    }
}

using Microsoft.EntityFrameworkCore;

public sealed class PlaceOrder(ShopDb db)
{
    public async Task<int> RunAsync(int cartId, CancellationToken ct)
    {
        var cart = await db.Carts.Include(c => c.Items)
            .SingleAsync(c => c.Id == cartId, ct);
        var order = new Order { CustomerId = cart.CustomerId };
        // Lines join through the navigation; EF sets OrderId during the save
        order.Lines.AddRange(cart.Items.Select(i => i.ToLine()));
        db.Orders.Add(order);
        db.Carts.Remove(cart); // its tracked items are deleted with it
        // One call, one transaction: order, lines and cart, all or nothing
        await db.SaveChangesAsync(ct);
        return order.Id;
    }
}

