using Microsoft.EntityFrameworkCore;

public sealed class OrderSaver(ShopDb db)
{
    public async Task SaveAsync(int productId, int qty, CancellationToken ct)
    {
        var strategy = db.Database.CreateExecutionStrategy();
        await strategy.ExecuteAsync(async () =>
        {
            await using var tx = await db.Database.BeginTransactionAsync(ct);
            // Runs right away, outside SaveChanges: only tx ties the two together
            await db.Products.Where(p => p.Id == productId).ExecuteUpdateAsync(
                s => s.SetProperty(p => p.Stock, p => p.Stock - qty), ct);
            // false keeps entity states, so a replay saves them again
            await db.SaveChangesAsync(acceptAllChangesOnSuccess: false, ct);
            await tx.CommitAsync(ct);
        });
        db.ChangeTracker.AcceptAllChanges();
    }
}
